import sys,json,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); r=Robot(); Q=[0.,1.,0.,0.]; SURF=.0202
class Writer:
 def __init__(self):
  o=r.get_obs(cameras=[]); self.pos=np.array(o.meta['proprio']['now'][7:10]);self.buf=[];self.seq=len(list(OUT.glob('action_*.npz')))
 def line(self,p,t):
  p=np.array(p);n=max(1,int(np.ceil(t/.05)));a=self.pos.copy()
  for k in range(1,n+1):self.buf.append(list(a+(p-a)*k/n)+Q)
  self.pos=p
 def flush(self,cameras=['practice_cam'],tag=''):
  while self.buf:
   a=np.array(self.buf[:200]);self.buf=self.buf[200:];self.seq+=1
   path=OUT/f'action_{self.seq:04d}';np.savez(str(path)+'.npz',actions=a,dt=.05,tag=tag)
   z=r.submit('ee_pose',a,dt=.05,cameras=cameras,video='none',video_fps=20,note=tag)
   (OUT/f'action_{self.seq:04d}.json').write_text(json.dumps(z.meta))
   if z.proprio is not None:np.save(str(path)+'_proprio.npy',z.proprio)
   for c,img in z.last.items():Image.fromarray(img).save(OUT/f'latest_{c}.png')
   print(self.seq,z.meta.get('control_steps'),z.meta.get('time_left_s'),z.meta.get('plan'),flush=True)
   if z.stopped or z.done: raise RuntimeError(z.meta)
 def travel(self,p):
  self.line([*self.pos[:2],.065],.45);self.line([p[0],p[1],.065],max(.6,np.linalg.norm(np.array(p[:2])-self.pos[:2])/.12));self.line(p,.6)
 def dip(self):
  self.travel([-.1,.155,.023]);self.line([-.1,.155,.023],.4);self.line([-.1,.155,.065],.6)
 def park(self):
  self.line([*self.pos[:2],.065],.7);self.line([-.10,.155,.09],2.5);self.flush(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],tag='park')
if __name__=='__main__':
 w=Writer()
 for i,d in enumerate([.001,.003,.005,.008,.012]):
  w.dip(); x=-.015-i*.035
  w.travel([x,-.155,SURF+.005]);w.line([x,-.155,SURF-d],.6);w.line([x,-.215,SURF-d],3);w.line([x,-.215,SURF+.01],.6)
  w.flush(tag=f'calibration depth {d}')
 w.park()
PY
